//! Filesystems whose contents are generated by the kernel or held only in
//! memory, which the walk does not descend into (docs/traversal.md, Mounts).

/// `statfs` `f_type` values. All are from linux/magic.h except configfs,
/// fusectl and mqueue, which that header does not carry; their values are
/// the kernel's, as `stat -f -c %t` prints for a mount of each. devtmpfs
/// reports the tmpfs magic, so it needs no entry of its own.
const VIRTUAL: [u32; 19] = [
    0x0000_9fa0, // proc (PROC_SUPER_MAGIC)
    0x6265_6572, // sysfs (SYSFS_MAGIC)
    0x0102_1994, // tmpfs and devtmpfs (TMPFS_MAGIC)
    0x8584_58f6, // ramfs (RAMFS_MAGIC)
    0x0000_1cd1, // devpts (DEVPTS_SUPER_MAGIC)
    0x0027_e0eb, // cgroup (CGROUP_SUPER_MAGIC)
    0x6367_7270, // cgroup2 (CGROUP2_SUPER_MAGIC)
    0x6462_6720, // debugfs (DEBUGFS_MAGIC)
    0x7472_6163, // tracefs (TRACEFS_MAGIC)
    0x7363_6673, // securityfs (SECURITYFS_MAGIC)
    0x6165_676c, // pstore (PSTOREFS_MAGIC)
    0xcafe_4a11, // bpf (BPF_FS_MAGIC)
    0x6265_6570, // configfs
    0x6573_5543, // fusectl
    0x1980_0202, // mqueue
    0x9584_58f6, // hugetlbfs (HUGETLBFS_MAGIC)
    0x4249_4e4d, // binfmt_misc (BINFMTFS_MAGIC)
    0xde5e_81e4, // efivarfs (EFIVARFS_MAGIC)
    0x0000_0187, // autofs (AUTOFS_SUPER_MAGIC)
];

pub fn is_virtual(f_type: u32) -> bool {
    VIRTUAL.contains(&f_type)
}
